@app.route("/tts")
def tts():
    if not _check_token():
        return jsonify({"error": "unauthorized"}), 401
    # 兼容两种参数格式：
    #  本服务：voice / text / rate / volume
    #  阅读器：v    / t    / r    / p (pitch) / s (style)
    voice = request.args.get("voice") or request.args.get("v") or "zh-CN-XiaoxiaoNeural"
    text = request.args.get("text") or request.args.get("t") or ""
    rate = request.args.get("rate") or request.args.get("r") or "+0%"
    pitch = request.args.get("p") or "+0Hz"
    volume = request.args.get("volume") or "+0%"
    style = request.args.get("s") or ""
    # 客户端健康探测：无文本也返回就绪（不报 400）
    if not text.strip():
        return jsonify({"status": "ok", "ready": True, "message": "send text with t= or text="}), 200

    # 阅读器格式的 r/p 是纯数字（0=正常），转成 edge-tts 接受的 +N% / +NHz
    try:
        if str(rate).lstrip("+-").replace(".", "", 1).isdigit() and "%" not in str(rate):
            rate = ("+" if not str(rate).startswith(("-", "+")) else "") + str(rate) + "%"
    except Exception:
        pass
    try:
        if str(pitch).lstrip("+-").replace(".", "", 1).isdigit() and "Hz" not in str(pitch).lower():
            pitch = ("+" if not str(pitch).startswith(("-", "+")) else "") + str(pitch) + "Hz"
    except Exception:
        pass

    try:
        import edge_tts
    except ImportError:
        return jsonify({"error": "edge-tts not installed, run: pip install edge-tts"}), 500

    async def synth():
        communicate = edge_tts.Communicate(text, voice, rate=rate, pitch=pitch, volume=volume)
        chunks = []
        async for chunk in communicate.stream():
            if chunk.get("type") == "audio" and chunk.get("data"):
                chunks.append(chunk["data"])
        return b"".join(chunks)

    try:
        audio = asyncio.run(synth())
    except Exception as e:
        sys.stderr.write(f"[edge-tts] error: {e}\n")
        sys.stderr.flush()
        return jsonify({"error": str(e)}), 500
    if not audio:
        return jsonify({"error": "no audio generated"}), 500
    return Response(audio, mimetype="audio/mpeg")


