#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""yt-dlp API service wrapper (with web panel)"""
import argparse, json, os, subprocess, urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

YTDLP = os.environ.get("YTDLP_BIN", "/root/yt-dlp/yt-dlp")
DOWNLOAD_DIR = os.environ.get("YTDLP_DIR", "/storage/emulated/0/Download/yt-dlp")

FORMAT_ALIAS = {
    "best": "best",
    "1080": "bestvideo[height<=1080]+bestaudio/best[height<=1080]",
    "720": "bestvideo[height<=720]+bestaudio/best[height<=720]",
    "480": "bestvideo[height<=480]+bestaudio/best[height<=480]",
    "mp3": "bestaudio/best",
}

def run_ytdlp(args, timeout=120):
    try:
        p = subprocess.run([YTDLP]+args, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return -1, "", "timeout"
    except FileNotFoundError:
        return -2, "", "yt-dlp not found"

def do_info(url):
    code, out, err = run_ytdlp(["-J", "--no-playlist", "--skip-download", url])
    if code != 0:
        return {"ok": False, "error": err.strip() or "unknown"}
    try:
        data = json.loads(out)
    except Exception as e:
        return {"ok": False, "error": f"parse failed: {e}"}
    formats = []
    seen = set()
    for f in data.get("formats", []):
        h = f.get("height") or 0
        res = f"{h}p" if h else "audio"
        key = (res, f.get("ext", ""))
        if key in seen:
            continue
        seen.add(key)
        formats.append({"id": f.get("format_id",""), "resolution": res, "ext": f.get("ext",""), "size": f.get("filesize") or f.get("filesize_approx") or 0})
    return {"ok": True, "title": data.get("title",""), "duration": data.get("duration"), "thumbnail": data.get("thumbnail",""), "uploader": data.get("uploader",""), "formats": formats[:30]}

def do_play(url, fmt="best"):
    f = FORMAT_ALIAS.get(fmt, fmt)
    code, out, err = run_ytdlp(["-g", "--no-playlist", "-f", f, url])
    if code != 0:
        return {"ok": False, "error": err.strip() or "unknown"}
    lines = [l for l in out.strip().splitlines() if l.strip()]
    if not lines:
        return {"ok": False, "error": "no url"}
    return {"ok": True, "url": lines[-1].strip()}

def do_download(url, fmt="best"):
    os.makedirs(DOWNLOAD_DIR, exist_ok=True)
    f = FORMAT_ALIAS.get(fmt, fmt)
    outtmpl = os.path.join(DOWNLOAD_DIR, "%(title)s [%(id)s].%(ext)s")
    try:
        p = subprocess.run([YTDLP, "--no-playlist", "-f", f, "-o", outtmpl, "--newline", "--no-warnings", url], capture_output=True, text=True, timeout=3600)
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "download timeout"}
    except FileNotFoundError:
        return {"ok": False, "error": "yt-dlp not found"}
    tail = (p.stdout + "\n" + p.stderr).strip().splitlines()[-15:]
    if p.returncode == 0:
        files = os.listdir(DOWNLOAD_DIR)
        return {"ok": True, "dir": DOWNLOAD_DIR, "files": files, "log": tail}
    return {"ok": False, "error": "download failed", "log": tail}

